/* Demonstrates moving data from a file into a pipe, and then from the pipe to standard output using two splice calls. */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>

int main(void) {
    int pipefd[2];
    int input_fd;
    ssize_t n_bytes;
    const char *test_content = "Zero-copy transfer via splice.\n";
    const char *temp_file = "/tmp/splice_test_input.txt";
    size_t len = strlen(test_content);

    // 1. Setup Input File
    input_fd = open(temp_file, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (input_fd == -1 || write(input_fd, test_content, len) == -1) {
        perror("Setup failed");
        exit(EXIT_FAILURE);
    }
    close(input_fd);
    input_fd = open(temp_file, O_RDONLY); // Re-open for reading
    if (input_fd == -1) { perror("Re-open failed"); unlink(temp_file); exit(EXIT_FAILURE); }

    // 2. Setup Pipe
    if (pipe(pipefd) == -1) {
        perror("pipe");
        close(input_fd); unlink(temp_file);
        return EXIT_FAILURE;
    }

    // 3. splice: File -> Pipe (fd_out must be a pipe)
    n_bytes = splice(input_fd, NULL, pipefd[1], NULL, len, 0);
    if (n_bytes == -1) {
        perror("splice file -> pipe");
        close(input_fd); close(pipefd[0]); close(pipefd[1]); unlink(temp_file);
        return EXIT_FAILURE;
    }
    printf("Stage 1: Transferred %zd bytes into pipe.\n", n_bytes);

    // 4. splice: Pipe -> STDOUT (fd_in must be a pipe)
    printf("Stage 2 Output: ");
    n_bytes = splice(pipefd[0], NULL, STDOUT_FILENO, NULL, len, 0);
    if (n_bytes == -1) {
        perror("splice pipe -> stdout");
    }

    // 5. Cleanup
    close(input_fd);
    close(pipefd[0]);
    close(pipefd[1]);
    unlink(temp_file);

    return EXIT_SUCCESS;
}
